import React, { useState } from 'react';
import { createUser, loginUser } from '../services/api'; 
import { useNavigate } from 'react-router-dom';
import useAuth from '../services/useAuth'; // Importar el hook
import "./UserForm.css"

const UserForm = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const navigate = useNavigate();
  const { login } = useAuth(); // Usar el hook

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (isLogin) {
        const response = await loginUser({ email, password });

              console.log('Respuesta del backend:', response.data);

        if (response.data.success) {
          const { id, email: userEmail, token } = response.data.user;
          login(id, userEmail, token); // Usar el método del hook
          alert('Inicio de sesión exitoso');
          navigate('/home');
        } else {
          alert('Email o contraseña incorrectos');
        }
      } else {
        // Lógica para crear usuario
        if (password !== confirmPassword) {
          alert('Las contraseñas no coinciden');
          return;
          
        }

        const newUserResponse = await createUser({ name, email, password });
        if (newUserResponse.data) {
          const { id, email: userEmail, token } = newUserResponse.data.user;
          login(id, userEmail, token); // Usar el método del hook
          alert('Usuario creado exitosamente');
          navigate('/home');
        } else {
          alert('Error al crear el usuario');
        }
      }
    } catch (error) {
      console.error('Error:', error);
      alert('Ocurrió un error, por favor intenta nuevamente.');
    }
  };


  return (
    <form onSubmit={handleSubmit} className="user-form">
      <h2 className="form-title">{isLogin ? 'Iniciar Sesión' : 'Crear Usuario'}</h2>
      <p className="form-subtitle">
        {isLogin
          ? 'Ingresá los siguientes datos para iniciar sesión'
          : 'Ingresá los siguientes datos para realizar el registro'}
      </p>

      {!isLogin && (
        <>
          <label htmlFor="name" className="input-label">Nombre</label>
          <input
            id="name"
            type="text"
            placeholder="NOMBRE"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            className="input-name"
          />
        </>
      )}

      <label htmlFor="email" className="input-label">Email</label>
      <input
        id="email"
        type="email"
        placeholder="EMAIL"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        required
        className="input-email"
      />

      <label htmlFor="password" className="input-label">Contraseña</label>
      <input
        id="password"
        type="password"
        placeholder="CONTRASEÑA"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        required
        className="input-password"
      />

      {!isLogin && (
        <>
          <label htmlFor="confirmPassword" className="input-label">Confirmar Contraseña</label>
          <input
            id="confirmPassword"
            type="password"
            placeholder="CONFIRMAR CONTRASEÑA"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            required
            className="input-password"
          />
        </>
      )}

      <p className="forgot-password">
        <a href="/forgot-password">Olvidé mi contraseña</a>
      </p>

      <button type="submit" className="submit-button">{isLogin ? 'Acceder' : 'Crear'}</button>

      <p className="toggle-form">
        {isLogin ? '¿No tenés cuenta? ' : '¿Ya tenés cuenta? '}
        <button type="button" onClick={() => setIsLogin(!isLogin)} className="toggle-button">
          {isLogin ? 'Registrate aquí' : 'Iniciar sesión'}
        </button>
      </p>
    </form>
  );
};

export default UserForm;
